def _sha1_hash32(data: bytes) -> int:
    return struct.unpack('<I', hashlib.sha1(data).digest()[:4])[0]

def _fmix32(value: int) -> int:
    value &= 4294967295
    value ^= value >> 16
    value = value * 2246822507 & 4294967295
    value ^= value >> 13
    value = value * 3266489909 & 4294967295
    value ^= value >> 16
    return value & 4294967295

def _permutation_table_digest() -> str:
    return sha256_bytes(canonical_json_bytes({'a': list(PERMUTATION_A), 'b': list(PERMUTATION_B)}))

def pure_minhash_values(shingles: set[str]) -> tuple[int, ...]:
    require(len(PERMUTATION_A) == len(PERMUTATION_B) == 128, 'permutation table length drift')
    require(_permutation_table_digest() == PERMUTATION_TABLE_SHA256, 'permutation table identity drift')
    values = [4294967295] * 128
    for shingle in sorted(shingles):
        mixed = _fmix32(_sha1_hash32(shingle.encode('utf-8')))
        values = [min(current, a_value * mixed + b_value & 4294967295) for current, a_value, b_value in zip(values, PERMUTATION_A, PERMUTATION_B)]
    return tuple(values)

def simulate_datasketch_score(left: set[str], right: set[str]) -> float:
    left_values = pure_minhash_values(left)
    right_values = pure_minhash_values(right)
    return sum((a == b for a, b in zip(left_values, right_values))) / len(left_values)

def score_with_datasketch(left: set[str], right: set[str]) -> float:
    try:
        from datasketch import MinHash
    except ImportError as exc:
        raise TroveCurataDuplicateError(f'datasketch import failed: {exc}') from exc

    def build(values: set[str]):
        sketch = MinHash(num_perm=128, seed=17, scheme='affine32')
        sketch.update_batch([value.encode('utf-8') for value in sorted(values)])
        return sketch
    provider = build(left).jaccard(build(right))
    simulated = simulate_datasketch_score(left, right)
    require(score_text(provider) == score_text(simulated), 'datasketch score diverged from retained affine32 replay')
    return provider
